contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs that drive C.transfer
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // require the arrays have same length to avoid index issues in the test itself
        require(_tos.length == v.length);

        bool reverted;
        // Call transfer and observe whether it reverts. We must call it at top-level.
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            reverted = false;
            // Observe the returned value in a local variable for the assertion below
            // (cannot read internal state of c otherwise)
            assert(ret == true);
        } catch {
            reverted = true;
        }

        // General rule: transfer reverts iff _tos.length == 0. For non-empty arrays it must not revert.
        assert(reverted == (_tos.length == 0));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs that drive C.transfer
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // require matching lengths and non-empty to avoid the require in C.transfer
        require(_tos.length > 0 && _tos.length == v.length);

        bool reverted = true;
        bool ret = false;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
        }

        // General rule: when _tos is non-empty and v matches length, transfer must not revert and must return true
        assert(reverted == false && ret == true);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // require non-empty and matching lengths to avoid the require in C.transfer
        require(_tos.length > 0 && _tos.length == v.length);

        bool reverted;
        bool result;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            result = r;
        } catch {
            reverted = true;
            result = false;
        }

        // General rule: under the precondition, the call must not revert and must return true
        assert(reverted == false && result == true);
    }

    receive() external payable { }
}
